    intent "AutoDRIVE author model with explicit frozen suspension and estimated physics"
    Ackermann chassis(ref = "autodrive_f1tenth_source_chassis")
    Standard front_left_wheel(ref = "autodrive_f1tenth_source_front_left_wheel", glue = (0.169999957085, 0.118000008166, 0.059, 0, 1, 0))
