    Standard rear_left_wheel(ref = "autodrive_f1tenth_source_rear_left_wheel", glue = (-0.159999966621, 0.118000023067, 0.059, 0, 1, 0))
    Standard rear_right_wheel(ref = "autodrive_f1tenth_source_wheel", glue = (-0.159999936819, -0.117999918759, 0.059, 0, 1, 0))
}

